import { ThemeProvider } from '@material-ui/core/styles';
import Navigation from 'components/Navigation';
import SpeedDials from 'components/SpeedDial';
import GlobalLoading from 'components/UI/GlobalLoading';
import Message from 'components/UI/Message';
import routerConfig from 'configs/routerConfig';
import theme from 'configs/theme';
import useTheme from 'hooks/useTheme';
import useVoice from 'hooks/useVoice';
import NotFoundPage from 'pages/NotFound';
import React, { Suspense, useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { BrowserRouter as Router, Route, Switch } from 'react-router-dom';
import { Element } from 'react-scroll';
import { getUserInfo } from 'redux/slices/userInfo.slice';
import Home from 'components/Home';
import { Redirect } from 'react-router-dom';

const { routes, renderRoutes } = routerConfig;

function App() {
  const [loading, setLoading] = useState(true);
  const dispatch = useDispatch();
  const { isAuth } = useSelector((state) => state.userInfo);

  useEffect(() => {
    dispatch(getUserInfo());
    setLoading(false);
  }, []);

  // In your router configuration
  <Route 
    path={ROUTES.ADMIN.WORD_APPROVAL} 
    render={() => {
      // Check if user is admin
      const isAdmin = localStorage.getItem('isAdmin') === 'true';
      return isAdmin ? <WordApproval /> : <Redirect to="/" />;
    }} 
  />

  return (
    <>
      {loading ? (
        <GlobalLoading />
      ) : (
        <ThemeProvider theme={theme}>
          <Router>
            <div className="dynonary-app">
              <Element name="scrollTop" />
              <Navigation />

              <Suspense fallback={<GlobalLoading />}>
                <Switch>
                  <Route exact path="/">
                    {isAuth ? renderRoutes(routes, isAuth) : <Redirect to="/home" />}
                  </Route>
                  <Route exact path="/home">
                    {isAuth ? <Redirect to="/" /> : <Home />}
                  </Route>
                  {renderRoutes(routes, isAuth)}
                  <Route>
                    <NotFoundPage />
                  </Route>
                </Switch>
              </Suspense>

              <div id="_overlay"></div>
              <Message />
              <SpeedDials />
            </div>
          </Router>
        </ThemeProvider>
      )}
    </>
  );
}

export default App;
